Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$RelativePath = "components\painel\MarketplacePaymentsPanel.tsx"
$Source = Join-Path $Root $RelativePath
$Backup = "$Source.payments-ui-$Timestamp.backup"
$PatchFile = Join-Path $env:TEMP "orcaly-payments-experience-$Timestamp.js"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

if (-not (Test-Path -LiteralPath $Source)) {
  throw "Arquivo não encontrado: $RelativePath"
}

Copy-Item -LiteralPath $Source -Destination $Backup -Force

try {
  $EncodedPatch = @'

'@

  $PatchBytes = [Convert]::FromBase64String(($EncodedPatch -replace "\s", ""))
  [IO.File]::WriteAllBytes($PatchFile, $PatchBytes)

  Write-Host "==> Reformulando a central de pagamentos" -ForegroundColor Cyan

  node $PatchFile
  $PatchExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "PATCH_NODE_EXIT_CODE=$PatchExitCode" -ForegroundColor Yellow

  if ($PatchExitCode -ne 0) {
    throw "O patch da central de pagamentos falhou."
  }

  $Checks = @(
    "ORCALY_PAYMENTS_EXPERIENCE_V2",
    "href: '/painel/pagamentos?tab=overview'",
    "Últimos recebimentos",
    "Recebimentos online ativos",
    "Formas de pagamento",
    "Condição do plano",
    "Situação da conta",
    "Aplicação automática",
    "Ver meu plano"
  )

  Write-Host ""
  Write-Host "==> Verificando a nova experiência" -ForegroundColor Cyan

  foreach ($Text in $Checks) {
    $Found = Select-String `
      -LiteralPath $Source `
      -Pattern $Text `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Found) {
      throw "Verificação falhou: $Text"
    }

    Write-Host "[OK] $Text" -ForegroundColor Green
  }

  $ForbiddenTexts = @(
    "Como funciona",
    "Tokens e dados técnicos ficam protegidos no servidor",
    "A conexão libera automaticamente Pix e cartões no marketplace",
    "abrir uma filial do caos"
  )

  foreach ($Text in $ForbiddenTexts) {
    $Found = Select-String `
      -LiteralPath $Source `
      -Pattern $Text `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if ($Found) {
      throw "Texto antigo ainda encontrado: $Text"
    }

    Write-Host "[REMOVIDO] $Text" -ForegroundColor DarkGreen
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan

  git --no-pager diff --check -- $RelativePath

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  Remove-Item `
    -LiteralPath (Join-Path $Root ".next") `
    -Recurse `
    -Force `
    -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan

  npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $Backup -Force
  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Green
  Write-Host "CENTRAL DE PAGAMENTOS REFORMULADA" -ForegroundColor Green
  Write-Host "==================================================" -ForegroundColor Green
  Write-Host "Visão Geral: conteúdo próprio e últimos recebimentos"
  Write-Host "Abas: navegação clara no celular e computador"
  Write-Host "Mercado Pago: textos comerciais e objetivos"
  Write-Host "Condições: comunicação profissional por plano"
  Write-Host "Botões: hierarquia visual e interações melhoradas"
  Write-Host ""
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Write-Host ""
  Write-Host "Falha detectada. Restaurando o componente anterior..." -ForegroundColor Yellow

  if (Test-Path -LiteralPath $Backup) {
    Copy-Item -LiteralPath $Backup -Destination $Source -Force
  }

  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $Backup -Force -ErrorAction SilentlyContinue

  throw
}
